import os
os.environ['OPENBLAS_NUM_THREADS']='1'
from rcb_hb import Session
import numpy as np, cma, multiprocessing as mp, time
S=None

def init():
 global S, base, lo, span
 S=Session(instance='/app/instance.npz');base=S.data.qpos[7:26].copy();lo=S.model.actuator_ctrlrange[:,0];span=np.diff(S.model.actuator_ctrlrange)[:,0]

def rollout(x,save=False,n=150):
 S.reset();q=base.copy();q[11:]=x[:8];q[10]=x[8]
 a=np.clip(2*(q-lo)/span-1,-1,1);cost=0; acts=[];states=[]
 for t in range(n):
  _,_,done=S.step(a);b=S.data.qpos[26:29];v=S.data.qvel[25:28];root=S.data.qpos[:3]
  target=S.data.xpos[12]+[.23,0,.22]
  dist=np.linalg.norm(b-target)
  if t>=10:cost+= min(dist,3)*2+.05*min(np.linalg.norm(v),20)+max(0,.9-root[2])*10
  if save:acts.append(a.copy());states.append(S.data.qpos.copy())
  if done:
   cost+=(n-t-1)*7;break
 if save:return cost,np.array(acts),np.array(states)
 return cost

if __name__=='__main__':
 init();pool=mp.Pool(12,initializer=init)
 x=np.array([-.1,-.15,-.4,-.3,-.1,.15,.4,-.3,0.])
 es=cma.CMAEvolutionStrategy(x,.3,{'popsize':36,'seed':12,'verbose':-9})
 best=1e9
 for k in range(250):
  xs=es.ask();fs=pool.map(rollout,xs);es.tell(xs,fs)
  if min(fs)<best:
   best=min(fs);x=xs[np.argmin(fs)];np.save('/app/output/catch_params.npy',x)
   f,a,st=rollout(x,True);np.savez('/app/output/catch.npz',actions=a,states=st,params=x)
   S.save_trajectory(a,'/app/output/trajectory.npz');np.save('/app/output/baseline.npy',a)
   print(k,round(best,3),len(a),np.round(st[-1,26:29],3),np.round(x,3),flush=True)
  if k%10==0: print('iter',k,round(min(fs),2),flush=True)
