import os
os.environ['OPENBLAS_NUM_THREADS']='1'
from rcb_hb import Session
import numpy as np,cma,multiprocessing as mp

def init():
 global s,base,lo,span,snap,ref,pre
 s=Session(instance='/app/instance.npz');lo=s.model.actuator_ctrlrange[:,0];span=np.diff(s.model.actuator_ctrlrange)[:,0]
 pp=np.load('/app/output/basket_v2_recovered.npz')['params'].reshape(3,19)
 pre=np.r_[np.load('/app/output/basket_v2.npz')['actions'][:441],np.array([pp[min(t//15,2)] for t in range(65)])]
 for a in pre:s.step(a)
 snap=s._snapshot();base=(pp[-1]+1)/2*span+lo;ref=getstate()

def getstate():
 d=s.data;R=d.xmat[1].reshape(3,3);pitch=np.arctan2(-R[2,0],np.hypot(R[2,1],R[2,2]));roll=np.arctan2(R[2,1],R[2,2]);yaw=np.arctan2(R[1,0],R[0,0]);fw=R[:2,0]/np.linalg.norm(R[:2,0]);co=np.dot(d.subtree_com[1,:2]-(d.site_xpos[2,:2]+d.site_xpos[3,:2])/2,fw);vel=np.dot(d.qvel[:2],fw)
 return np.array([pitch,roll,yaw,co,vel])

def rollout(x,save=False):
 s._restore(snap);cost=0;acts=[];states=[]
 for t in range(300):
  st=getstate();q=base.copy();q[[4,9]]+=x[0]+x[1]*(st[0]-ref[0])+x[2]*s.data.qvel[4]+x[3]*(st[3]-ref[3])+x[4]*st[4]
  q[[1,6]]+=x[5]+x[6]*(st[1]-ref[1])+x[7]*s.data.qvel[3]
  q[[0,5]]+=x[8]*(st[2]-ref[2])+.1*s.data.qvel[5]
  a=np.clip(2*(q-lo)/span-1,-1,1);s.step(a);d=s.data
  cost+=np.linalg.norm(d.qvel[:3])**2+5*max(0,1.65-d.site_xpos[6,2])**2+5*(1-d.xmat[12,8])
  if save:acts.append(a);states.append(d.qpos.copy())
  if d.qpos[2]<.65:cost+=(300-t)*100;break
 if save:return cost,np.array(acts),np.array(states)
 return cost
if __name__=='__main__':
 init();pool=mp.Pool(4,initializer=init);es=cma.CMAEvolutionStrategy([0,1,.2,2,.5,0,1,.2,.8],.1,{'popsize':24,'seed':35});best=1e9
 for k in range(120):
  xs=es.ask();fs=pool.map(rollout,xs);es.tell(xs,fs)
  if min(fs)<best:
   best=min(fs);x=xs[np.argmin(fs)];f,a,st=rollout(x,True);np.savez('/app/output/postbalance.npz',params=x,actions=a,states=st,base=base,ref=ref)
   print(k,best,len(a),st[-1,:3],flush=True)
  if k%10==0:print('iter',k,min(fs),flush=True)
